pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        // test runner account is address(this) in Foundry; deploy C from this test contract
        c = new C();
        deployer = address(this); // admin was set to msg.sender at construction (this contract)
    }

    // fuzz NewOwner; the property: when called by admin, setOwner should succeed and set owner to NewOwner
    function testFuzz_property(address newOwner) public {
        // keep domain wide but exclude zero address only to avoid trivial issues if desired
        // it's acceptable for owner to be set to zero in reference; we keep it wide so fuzzer can find differences
        // Call setOwner as admin (this contract is admin)
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // single assertion: reference implementation always succeeds and updates owner to newOwner when called by admin
        // We observe via public getter owner()
        // For the correct contract: ok == true and c.owner() == newOwner for all newOwner inputs
        // The buggy mutant will sometimes require msg.sender == owner, causing ok==false or owner unchanged for some inputs
        assertTrue(ok && c.owner() == newOwner);
    }
}

