pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the new owner address. The property: when the admin (deployer) calls setOwner(newOwner),
    // the reference contract always sets owner() == newOwner. The mutant sometimes blocks admin
    // because it requires msg.sender == owner, so this fuzz will find a newOwner that distinguishes.
    function testFuzz_property(address newOwner) public {
        // keep domain wide; newOwner can be any address (including zero)
        // call as the deployer/admin (setUp deployer is this test contract's address during setUp)
        // The admin when deploying C was address(this) in setUp, but subsequent calls from this test
        // will have msg.sender == address(this) as well, so we directly call setOwner.

        bool ok;
        try c.setOwner(newOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if call succeeded, owner() must equal the provided newOwner.
        // The reference satisfies: call always succeeds and owner()==newOwner for all newOwner.
        // The mutant can fail (either revert or leave owner unchanged) for some newOwner.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If the call reverted, the reference never reverts; to keep property universal for
            // the reference, we still require that the reference would never revert. Here we assert
            // false to make this test fail on mutants that revert. However, per instruction we must
            // have exactly one assertTrue reading c. So encode the combined property as:
            // after calling setOwner(newOwner), owner() == newOwner must hold (if call reverted, owner unchanged != newOwner and assertion fails).
            // To conform to single assertTrue requirement and read c only, we check owner equals newOwner
            // irrespective of ok — for the reference this holds; the mutant will produce a counterexample.
            assertTrue(c.owner() == newOwner);
        }
    }
}

