pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: actor who will call setOwner. We require it not to be address(0) to keep domain wide but valid.
    function testFuzz_property(address caller, address newOwner) public {
        // Keep domain wide: don't exclude most addresses. Just avoid 0 address for clarity.
        vm.assume(caller != address(0));

        // Ensure caller is the current owner: make the contract's owner be caller by having deployer (setUp's msg.sender)
        // call setOwner(caller). The deployer is the Test contract address in forge; in our setup c was deployed by this test
        // contract, so the test contract is the admin and initial owner. First set owner to caller via admin call.
        bool ok;
        try c.setOwner(caller) {
            ok = true;
        } catch {
            ok = false;
        }
        // If the above admin call failed, we cannot arrange caller as owner; in that case skip by assume to keep domain wide.
        vm.assume(ok == true);

        // Now caller (who is current owner) calls setOwner(newOwner).
        vm.prank(caller);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assert): If the caller equals the current owner, then invoking setOwner should succeed
        // and update owner() to the provided newOwner. The reference contract satisfies this for all inputs; the mutant
        // that requires msg.sender == owner inside the onlyAdmin-guard will break when admin call logic changes and
        // may cause the final call to revert or leave owner unchanged. We assert that the call succeeded and owner()==newOwner.
        assertTrue(ok && c.owner() == newOwner);
    }
}

