pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: caller (an address that will act as msg.sender) and newOwner (the address to set)
    function testFuzz_property(address caller, address newOwner) public {
        // admissible domain: caller must be non-zero to be meaningful; keep wide otherwise
        vm.assume(caller != address(0));

        // Ensure caller is the current owner: first, fetch deployer-owner (constructor set owner to deployer)
        address deployer = address(this); // in setUp(), Test contract deployed C via new C(); msg.sender was this test contract
        // Confirm deployer is current owner
        assertEq(c.owner(), deployer);

        // If caller != deployer, we need to make caller the owner first by having deployer set owner to caller
        if (caller != deployer) {
            // deployer (this) calls setOwner(caller)
            bool ok;
            try c.setOwner(caller) {
                ok = true;
            } catch {
                ok = false;
            }
            // On the reference contract this must succeed and owner becomes caller
            require(ok, "setup: reference failed to set owner to caller");
            assertEq(c.owner(), caller);
        }

        // Now caller equals current owner. We will have caller call setOwner(newOwner).
        bool ok2;
        // use vm.prank to make the call come from caller
        vm.prank(caller);
        try c.setOwner(newOwner) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // The reference contract guarantees that when msg.sender is the current owner, setOwner succeeds and updates owner()
        // Thus assert that the call succeeded and owner() == newOwner
        assertTrue(ok2 && c.owner() == newOwner);
    }
}

