import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: attacker (an arbitrary address) and newOwner (an arbitrary address)
    function testFuzz_property(address attacker, address newOwner) public {
        // keep addresses non-zero to be realistic
        vm.assume(attacker != address(0));
        vm.assume(newOwner != address(0));
        // Ensure attacker is not the deployer/admin
        address deployer = address(this); // setUp deployed c from this test contract
        vm.assume(attacker != deployer);

        // 1) Initially, owner() == deployer
        address initialOwner = c.owner();
        // sanity: initial owner must be the deployer
        // (we don't assert here because single assert required at end)

        // 2) The attacker cannot call setOwner because only admin (deployer) may call it in the reference.
        // We let the attacker attempt to call setOwner to set owner to newOwner.
        bool ok;
        vm.prank(attacker);
        try c.setOwner(newOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }

        // In the correct contract, only the deployer (admin) can call setOwner, so this call by attacker must fail.
        // The buggy contract (mutant) allows the current owner to act as admin; if attacker equals the current owner
        // the mutant would allow it. We ensured attacker != deployer, but attacker could equal initialOwner only if
        // a weird deploy context; to allow fuzzer to find a failing case for the mutant, keep domain wide.

        // Single required assertion: in the correct contract the call by a non-admin attacker cannot succeed.
        // This reads c through its public surface by observing whether the call returned true (ok).
        assertTrue(!ok);
    }
}

