pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller who will attempt to call setOwner, and a candidate newOwner
    function testFuzz_property(address caller, address newOwner) public {
        // Keep domain wide but avoid zero-address for clarity (still wide):
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Determine the deployer/admin (the address that deployed c is this test contract by default)
        address deployer = address(this);

        // If caller is deployer, setOwner should succeed and set owner to newOwner.
        // If caller is not deployer, in the reference contract setOwner must revert (only admin allowed)
        // We therefore check a universal property: after caller attempts setOwner, either the call reverted
        // (so owner did not change from its initial value) OR the caller was the deployer.

        // Record initial owner (constructor set it to deployer)
        address initialOwner = c.owner();

        // Try call as caller
        bool ok;
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // Single assertion: if the call succeeded (ok==true), then caller must be deployer.
        // This is true for the reference: only deployer can cause success. The mutant that allows current owner
        // (which may not be deployer) to succeed will violate this for some fuzzed caller/newOwner.
        assertTrue(!ok || caller == deployer);
    }
}

