pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        // test runner is the deployer of C in setUp
        deployer = address(this);
        c = new C();
    }

    // fuzzed params: caller and candidate new owner
    function testFuzz_property(address caller, address candidate) public {
        // widen domain: avoid zero address for candidate (still wide)
        // but allow caller to be any address (including deployer and non-deployer)
        if (candidate == address(0)) {
            candidate = address(1);
        }

        // Perform the call as `caller` to setOwner(candidate).
        // We capture whether the call succeeded and then read c.owner().
        bool ok;
        address prevOwner = c.owner();

        // impersonate caller
        vm.prank(caller);
        try c.setOwner(candidate) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        address afterOwner = c.owner();

        // General rule (single assertion): If the call succeeded (ok == true)
        // then the caller must be the original deployer (admin). This holds for
        // the reference implementation for all inputs, but the mutant allows
        // the current owner to call setOwner and succeed even when caller != deployer.
        // We express the rule by observing that whenever setOwner returned true,
        // c.owner() equals deployer iff caller == deployer. Concretely, we assert
        // that if ok is true then caller == deployer OR afterOwner == caller.
        // To craft a single invariant that the correct contract always satisfies
        // but the mutant violates: in the correct contract, a successful setOwner
        // can only come from deployer, so whenever ok is true it must be that caller == deployer
        // (and owner becomes candidate). We assert that: if ok then caller == deployer.

        assertTrue(!ok || caller == deployer);
    }
}

